using System;
using System.Collections.Generic;
using UnityEngine.TextCore.Text;
using TextCoreSettings = UnityEngine.TextCore.Text.TextGenerationSettings;

namespace UnityEngine
{
    /// <summary>
    /// The text of an IMGUI style, generated by TextCore: converts a <see cref="GUIStyle"/> into
    /// <see cref="TextGenerationSettings"/>, caches handles by settings hash, and answers the
    /// preferred size, line height, glyph meshes and cursor positions. It is IMGUI's only text
    /// engine: a text that cannot be generated (no font, or no font asset for it) is reported and
    /// measures as nothing, never by another route.
    /// </summary>
    internal partial class IMGUITextHandle : TextHandle
    {
        const int MaxCachedHandles = 512;

        static readonly Dictionary<int, IMGUITextHandle> s_Handles = new Dictionary<int, IMGUITextHandle>();
        static readonly LinkedList<TextHandleTuple> s_Lru = new LinkedList<TextHandleTuple>();
        static TextSettings s_EditorTextSettings;

        internal LinkedListNode<TextHandleTuple> tuple;
        internal static Func<Object> GetEditorTextSettings;
        internal static Func<int, FontAsset, FontAsset> GetBlurryFontAssetMapping;
        internal bool isCachedOnNative;

        internal partial class TextHandleTuple
        {
            public float lastTimeUsed;
            public int hashCode;

            public TextHandleTuple(float lastTimeUsed, int hashCode)
            {
                this.lastTimeUsed = lastTimeUsed;
                this.hashCode = hashCode;
            }
        }

        public IMGUITextHandle() { }

        internal static void EmptyCache() => EmptyManagedCache();

        internal static void EmptyManagedCache()
        {
            while (s_Lru.First != null) Forget(s_Lru.First.Value.hashCode);
            s_Handles.Clear();
        }

        /// <summary>The text settings IMGUI's font assets belong to: the Editor's text settings
        /// (through <see cref="GetEditorTextSettings"/> when something replaced the source).</summary>
        static TextSettings ResolveTextSettings()
        {
            if (s_EditorTextSettings == null)
                s_EditorTextSettings = GetEditorTextSettings != null ? GetEditorTextSettings() as TextSettings : UnityEditor.EditorTextSettings.defaultTextSettings;
            return s_EditorTextSettings;
        }

        /// <summary>The size a style without a font size draws at when its font gives none.</summary>
        const float FallbackFontSize = 13f;

        /// <summary>The padding of glyph quads. It changes no measurement; it is set because the
        /// settings object is shared with UI Toolkit, which sets its own per font asset.</summary>
        const float GlyphQuadPadding = 6f;

        static bool s_ReportedMissingFont;
        static Font s_FontWithoutAsset;

        /// <summary>Says once that IMGUI text has no font to be generated with; such text has no size
        /// and is not drawn (the engine was started without its fonts, as in a unit test host).</summary>
        static void ReportMissingFont(GUIStyle style, bool noFont)
        {
            if (s_ReportedMissingFont) return;
            s_ReportedMissingFont = true;
            Debug.LogError(noFont
                ? $"Unbound: IMGUI text cannot be generated: style '{style.name}' has no font and there is no default font. Text is neither measured nor drawn."
                : $"Unbound: IMGUI text cannot be generated: no font asset could be made for the font of style '{style.name}'. Text is neither measured nor drawn.");
        }

        /// <summary>Forgets the handles, the text settings in use and that a missing font was reported.</summary>
        internal static void ResetForTests()
        {
            EmptyManagedCache();
            s_EditorTextSettings = null;
            s_ReportedMissingFont = false;
            s_FontWithoutAsset = null;
        }

        internal static bool TryConvertStyleToSettings(TextCoreSettings tgs, GUIStyle style, Color textColor, string text, Rect rect) =>
            TryConvertStyleToSettings(tgs, style, textColor, new RenderedText(text ?? ""), rect);

        internal static bool TryConvertStyleToSettings(TextCoreSettings tgs, GUIStyle style, Color textColor, RenderedText text, Rect rect)
        {
            var textSettings = ResolveTextSettings();
            tgs.textSettings = textSettings;
            if (textSettings == null) return false;

            var font = style.ResolvedFont;
            if (font == null)
            {
                ReportMissingFont(style, true);
                return false;
            }

            tgs.fontSize = style.fontSize > 0 ? style.fontSize : (font.fontSize > 0 ? font.fontSize : FallbackFontSize);
            tgs.fontStyle = TextGeneratorUtilities.LegacyStyleToNewStyle(style.fontStyle);
            tgs.fontWeight = TextFontWeight.Regular;
            // A font no asset could be made for is not tried again with every text.
            tgs.fontAsset = ReferenceEquals(font, s_FontWithoutAsset) ? null : textSettings.GetCachedFontAsset(font);
            if (tgs.fontAsset == null)
            {
                s_FontWithoutAsset = font;
                ReportMissingFont(style, false);
                return false;
            }

            tgs.screenRect = new Rect(0f, 0f, rect.width, rect.height);
            tgs.pixelsPerPoint = GUIUtility.pixelsPerPoint;
            tgs.isEditorRenderingModeBitmap = false;
            tgs.renderedText = text;

            var alignment = style.alignment;
            if (style.imagePosition == ImagePosition.ImageAbove)
            {
                alignment = alignment switch
                {
                    TextAnchor.MiddleLeft or TextAnchor.LowerLeft => TextAnchor.UpperLeft,
                    TextAnchor.MiddleCenter or TextAnchor.LowerCenter => TextAnchor.UpperCenter,
                    TextAnchor.MiddleRight or TextAnchor.LowerRight => TextAnchor.UpperRight,
                    _ => alignment,
                };
            }
            tgs.textAlignment = TextGeneratorUtilities.LegacyAlignmentToNewAlignment(alignment);
            tgs.overflowMode = style.clipping switch
            {
                TextClipping.Clip => TextOverflowMode.Masking,
                TextClipping.Ellipsis => TextOverflowMode.Ellipsis,
                _ => TextOverflowMode.Overflow,
            };
            tgs.textWrappingMode = rect.width > 0f && style.wordWrap
                ? TextWrappingMode.PreserveWhitespace
                : TextWrappingMode.PreserveWhitespaceNoWrap;
            tgs.emojiFallbackSupport = true;
            tgs.richText = style.richText;
            tgs.extraPadding = GlyphQuadPadding;
            tgs.parseControlCharacters = false;
            tgs.isPlaceholder = false;
            tgs.isRightToLeft = false;
            tgs.characterSpacing = 0f;
            tgs.wordSpacing = 0f;
            tgs.paragraphSpacing = 0f;
            tgs.color = textColor;
            tgs.isIMGUI = true;
            tgs.shouldConvertToLinearSpace = false;
            return true;
        }

        /// <summary>What a caller does with a handle. A text is generated into its handle's own
        /// text info only where that is read again, since the generation settings are one object
        /// per thread, overwritten by the next conversion (a line height query is one): a text
        /// that is only measured keeps just its preferred size.</summary>
        internal enum Use
        {
            /// <summary>Only the preferred size is read.</summary>
            Measure,
            /// <summary>The glyph meshes are drawn this frame: the text info is kept while the
            /// text keeps being drawn (the temporary cache).</summary>
            Draw,
            /// <summary>Cursor positions or characters are queried: the text info is kept with
            /// the handle (the permanent cache).</summary>
            Query,
        }

        internal static IMGUITextHandle GetTextHandle(GUIStyle style, Rect position, string content, Color32 textColor) =>
            GetTextHandle(style, position, new RenderedText(content ?? ""), textColor, Use.Query);

        internal static IMGUITextHandle GetTextHandle(GUIStyle style, Rect position, string content, Color32 textColor, ref bool isCached)
        {
            var tgs = TextHandle.settings;
            isCached = TryConvertStyleToSettings(tgs, style, textColor, new RenderedText(content ?? ""), position) && s_Handles.ContainsKey(tgs.GetHashCode());
            return GetTextHandle(style, position, new RenderedText(content ?? ""), textColor, Use.Draw);
        }

        /// <summary>The handle of a text laid out in <paramref name="position"/>'s size, generated
        /// and measured, its text info kept as <paramref name="use"/> needs; null (reported) when
        /// the style has no font to generate it with.</summary>
        internal static IMGUITextHandle GetTextHandle(GUIStyle style, Rect position, RenderedText content, Color32 textColor, Use use)
        {
            var tgs = TextHandle.settings;
            if (!TryConvertStyleToSettings(tgs, style, textColor, content, position))
                return null;
            int hash = tgs.GetHashCode();
            bool created = !s_Handles.TryGetValue(hash, out var handle);
            if (created)
            {
                if (s_Handles.Count >= MaxCachedHandles && s_Lru.First != null) Forget(s_Lru.First.Value.hashCode);
                handle = new IMGUITextHandle();
                handle.tuple = new LinkedListNode<TextHandleTuple>(new TextHandleTuple(Time.realtimeSinceStartup, hash));
                s_Handles[hash] = handle;
                s_Lru.AddLast(handle.tuple);
            }
            else
            {
                s_Lru.Remove(handle.tuple);
                s_Lru.AddLast(handle.tuple);
            }
            // Each branch generates at most once, and only while the settings are this text's.
            if (use == Use.Query && !handle.IsCachedPermanent)
            {
                handle.AddTextInfoToPermanentCache();
                handle.UpdatePreferredSize();
            }
            else if (use == Use.Draw && !handle.IsCachedPermanent)
            {
                bool kept = handle.IsCachedTemporary;
                handle.AddTextInfoToTemporaryCache(hash);
                if (!kept) handle.UpdatePreferredSize();
            }
            else if (created)
            {
                handle.UpdateWithHash(hash);
                handle.UpdatePreferredSize();
            }
            return handle;
        }

        /// <summary>Drops a handle and the text info it keeps.</summary>
        static void Forget(int hash)
        {
            if (!s_Handles.Remove(hash, out var handle)) return;
            s_Lru.Remove(handle.tuple);
            handle.RemoveTextInfoFromTemporaryCache();
            handle.RemoveTextInfoFromPermanentCache();
        }

        internal static float GetLineHeight(GUIStyle style)
        {
            var tgs = TextHandle.settings;
            if (!TryConvertStyleToSettings(tgs, style, Color.white, "", Rect.zero))
                return 0f;
            return TextHandle.GetLineHeightDefault(tgs);
        }

        internal Vector2 GetPreferredSize() => preferredSize;

        /// <summary>How many characters of the first line fit in a width, by their advances.</summary>
        internal int GetNumCharactersThatFitWithinWidth(float width)
        {
            AddTextInfoToPermanentCache();
            var info = textInfo;
            if (info.lineCount == 0) return 0;
            int count = info.lineInfo[0].characterCount;
            float used = 0f;
            int i;
            for (i = 0; i < count; i++)
            {
                used += info.textElementInfo[i].xAdvance - info.textElementInfo[i].origin;
                if (used > width) break;
            }
            return i;
        }
    }
}
